import rawLearnsets from "@/data/learnsets.json";

/**
 * speciesId -> Gen 9 move ids, generated by scripts/fetch-smogon-data.mjs from
 * @pkmn/dex (MIT, data derived from Pokémon Showdown). Every id in the values
 * is a key of @/data/moves.json.
 */
export const LEARNSETS: Record<string, string[]> = rawLearnsets as unknown as Record<
  string,
  string[]
>;

export function getLearnset(speciesId: string): string[] {
  return LEARNSETS[speciesId] ?? [];
}
